from __future__ import annotations
import hashlib,json,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'experiments/results/v1_1/phase4_source_feasibility/4_1_1'
V1='d977a32c2f20efa5f8e0d0349d40b270ecabeca2'; FOUNDATION='b2c624c84743dbb403b56ed9be28dcfa2c1cb105'; HARDENING='066e9b9b131d2ec843133fe34ca185ddbd0d8d79'
def sha(p):
 h=hashlib.sha256();
 with p.open('rb') as f:
  for c in iter(lambda:f.read(1024*1024),b''):h.update(c)
 return h.hexdigest()
def write(p,text): p.parent.mkdir(parents=True,exist_ok=True); p.write_text(text)
def main():
 if OUT.exists(): raise SystemExit('Phase 4.1.1 artifacts already exist; refusing overwrite')
 for d in ['protocol','audit','source_evaluation','observability','artifacts','quality','reports','hashes']: (OUT/d).mkdir(parents=True)
 protocol={'phase':'4.1.1','title':'runtime source feasibility and instrumentation decision','frozen_v1_commit':V1,'phase40_41_foundation_commit':FOUNDATION,'hardening_commit':HARDENING,'no_v1_modification':True,'no_phase42':True,'no_model_training':True,'no_benchmark_integration':True,'decision_options':['A_REAL_EXTERNAL_RUNTIME','B_CONTROLLED_RUNTIME','C_PARTIALLY_FEASIBLE','D_NO_LEGITIMATE_RUNTIME_SOURCE'],'real_timestamped_source':'NOT AVAILABLE','controlled_runtime_instrumentation':'NOT IMPLEMENTED; no legitimate existing workload execution path identified','historical_trace':'Alibaba GPU2020; replayable historical data, not synchronized runtime evidence'}
 write(OUT/'protocol/phase411_protocol.json',json.dumps(protocol,indent=2,sort_keys=True)+'\n')
 audit='''# Phase 4.1.1 Repository Audit\n\n| Capability | Existing implementation | Reusable? | Missing? | Proposed action |\n|---|---|---|---|---|\n| Canonical event model | `src/data_foundation/foundation.py` | Yes | No | Reuse |\n| Runtime collector | `src/phase4/observability.py` | Yes | Legitimate source absent | Keep as adapter boundary |\n| Persistent event store | `PersistentEventStore` in `src/phase4/observability.py` | Yes | No for engineering persistence | Reuse; no second store |\n| Replay | `ObservationReplay` | Yes | No for deterministic replay | Reuse |\n| Observability API | `ObservabilityAPI` | Yes | Live source absent | Reuse when a source exists |\n| Workload executor | No project-owned real infrastructure execution path identified | N/A | Yes | Do not fabricate one |\n| Simulator | No approved simulator with real event semantics identified | N/A | Yes | No simulated source added |\n| Telemetry source | Alibaba historical sampled telemetry only | Limited | Synchronized runtime semantics | Classify as historical trace |\n| Scheduler/resource source | No legitimate live source | N/A | Yes | Record UNAVAILABLE |\n| Environment identity | One Alibaba trace identity | Limited | Independent runtime environment | Preserve one identity only |\n| V1 integration | Frozen control boundary | Yes | No | Do not modify |\n\nRepository state was verified at the start of the audit. No existing process was found that emits a synchronized canonical runtime event stream with the required source-record and environment semantics.\n'''
 write(OUT/'audit/repository_audit.md',audit)
 sources=[
 {'source_id':'alibaba_gpu2020_historical','source_class':'HISTORICAL_TRACE','engineering_status':'REPLAYABLE DATA ONLY','research_status':'REJECT AS LIVE RUNTIME SOURCE','timestamp_quality':'APPROXIMATE/PARTIAL; runtime decision synchronization unknown','decision_time_support':'NOT PROVEN','environment_identity':'ONE TRACE IDENTITY','provenance':'SOURCE AND PROCESSED PROVENANCE PARTIAL','reproducibility':'REPLAYABLE PROCESSED ARTIFACTS; NOT REPRODUCIBLE RUNTIME','acceptance_decision':'REJECT','reason':'Historical rows and sampled telemetry do not prove actual event occurrence at a synchronized runtime decision boundary.','limitations':'No prediction timestamp, scheduler identity/state, queue, live allocation, or independent runtime environment.'},
 {'source_id':'phase4_persistent_event_store','source_class':'UNUSABLE','engineering_status':'STORAGE INFRASTRUCTURE ONLY','research_status':'NOT A SOURCE','timestamp_quality':'PRESERVES INPUT QUALITY; DOES NOT CREATE IT','decision_time_support':'DEPENDS ON INPUT SOURCE','environment_identity':'DEPENDS ON INPUT SOURCE','provenance':'REQUIRES INPUT PROVENANCE','reproducibility':'DETERMINISTIC STORAGE/REPLAY','acceptance_decision':'DEFER','reason':'A store is not an event source and cannot manufacture runtime observations.','limitations':'No events are connected without a legitimate producer.'},
 {'source_id':'synthetic_test_fixtures','source_class':'SYNTHETIC_TEST_FIXTURE','engineering_status':'TEST ONLY','research_status':'REJECT AS RESEARCH SOURCE','timestamp_quality':'CONTROLLED TEST VALUES','decision_time_support':'TEST CONTRACT ONLY','environment_identity':'CONTROLLED TEST LABEL','provenance':'SYNTHETIC/TEST-ONLY','reproducibility':'DETERMINISTIC FIXTURE','acceptance_decision':'REJECT','reason':'Artificial records validate software contracts only.','limitations':'No real infrastructure occurrence or generalization evidence.'},
 {'source_id':'external_runtime_source','source_class':'UNUSABLE','engineering_status':'NOT CONNECTED','research_status':'DEFER','timestamp_quality':'UNKNOWN','decision_time_support':'UNKNOWN','environment_identity':'UNKNOWN','provenance':'UNKNOWN','reproducibility':'UNKNOWN','acceptance_decision':'DEFER','reason':'No external source was acquired or silently integrated.','limitations':'Requires explicit source approval, license, provenance, timestamp, and environment evaluation.'}
 ]
 write(OUT/'source_evaluation/source_inventory.json',json.dumps(sources,indent=2)+'\n')
 obs=['workload_received','task_created','scheduling_event','resource_requested','resource_allocated','prediction_input_snapshot','prediction_generated','execution_started','telemetry_observed','failure_detected','diagnosis_started','recovery_started','recovery_completed','validation_completed','workload_completed','queue_state','scheduler_state','allocation_state','resource_state','node_identity_state','gpu_identity_state','environment_identity','provenance','source_record_identity','reproducibility']
 rows=[]
 for item in obs:
  if item in {'workload_received','task_created'}: av='PARTIAL'; evidence='Alibaba source fields exist, but occurrence/runtime semantics are historical'
  elif item in {'prediction_input_snapshot','prediction_generated'}: av='UNAVAILABLE'; evidence='No synchronized runtime prediction event source'
  elif item in {'telemetry_observed'}: av='PARTIAL'; evidence='Sampled sensor/machine tables exist; timing relative to decision unknown'
  elif item in {'environment_identity','provenance','source_record_identity','reproducibility'}: av='PARTIAL'; evidence='Metadata and processed provenance exist; runtime lineage incomplete'
  else: av='UNAVAILABLE'; evidence='No legitimate connected runtime source'
  rows.append({'requirement':item,'available':av,'evidence':evidence,'quality':'UNKNOWN unless proven by a real source','notes':'No fabrication; schema support is not data availability'})
 write(OUT/'observability/observability_matrix.json',json.dumps(rows,indent=2)+'\n')
 gate={'candidate_source_identified':'PARTIAL','legitimate_runtime_source':'NOT AVAILABLE','timestamped_collection':'NOT AVAILABLE','decision_time_support':'NOT AVAILABLE','timestamp_integrity':'PARTIAL','provenance':'PARTIAL','environment_identity':'PARTIAL','resource_observability':'NOT AVAILABLE','scheduler_observability':'NOT AVAILABLE','reproducibility':'PARTIAL','persistent_integration':'READY_FOR_FUTURE_SOURCE','replay':'READY_FOR_FUTURE_SOURCE','v1_boundary':'READY','historical_protection':'PASS','focused_tests':'PASS_EXISTING_TESTS','final_source_decision':'D — NO LEGITIMATE RUNTIME SOURCE CURRENTLY AVAILABLE'}
 write(OUT/'quality/final_gate.json',json.dumps(gate,indent=2)+'\n')
 write(OUT/'artifacts/source_feasibility.json',json.dumps({'sources':sources,'final_decision':'D — NO LEGITIMATE RUNTIME SOURCE CURRENTLY AVAILABLE','phase42_authorization':'NOT AUTHORIZED','controlled_runtime_instrumentation':'NOT IMPLEMENTED','reason':'The repository has reusable observability infrastructure but no legitimate existing runtime process or synchronized external runtime event source.','next_requirement':'Connect an explicitly approved, timestamped, provenance-preserving runtime source or instrument an actual project-owned controlled workload process.'},indent=2)+'\n')
 write(OUT/'quality/v1_historical_boundary.json',json.dumps({'frozen_v1_commit':V1,'verified_repository_head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'historical_paths_modified':False,'v1_modified':False,'model_training':False,'benchmark_integration':False},indent=2)+'\n')
 report='''# PHASE 4.1.1 — RUNTIME SOURCE FEASIBILITY REPORT\n\n## 1. Repository audit\n\nThe repository already contains canonical events, decision-time snapshots, provenance, timestamp validation, a collector, append-only persistent storage, deterministic replay, and a bounded observability API. The audit found no project-owned workload executor, approved simulator with real event semantics, live telemetry source, scheduler source, or synchronized external runtime event stream. The existing store is infrastructure, not a source.\n\n## 2. Candidate source inventory and classification\n\n| Candidate | Classification | Engineering status | Research status | Decision |\n|---|---|---|---|---|\n| Alibaba GPU2020 processed trace | HISTORICAL_TRACE | Replayable data | Not a live runtime source | REJECT |\n| Persistent event store | UNUSABLE as source | Storage infrastructure | Not research evidence | DEFER |\n| Synthetic test fixtures | SYNTHETIC_TEST_FIXTURE | Test only | Not research evidence | REJECT |\n| External runtime source | UNUSABLE / not connected | Not connected | Deferred | DEFER |\n\n## 3. Observability requirements matrix\n\nThe machine-readable matrix is `observability/observability_matrix.json`. Workload/task fields and sampled telemetry are partial historical evidence; prediction timestamps, scheduler, queue, allocation, live resource, node, GPU, recovery, and validation runtime events are unavailable. Provenance and source identity are partial, while synchronized runtime semantics are not proven.\n\n## 4. Decision-time feasibility\n\nThe project cannot currently prove `snapshot_time <= prediction_generated_time <= prediction_decision_time` for a real runtime event stream. The Phase 4.1 contracts can enforce this relationship once a legitimate source provides the timestamps, but a schema or persistent store cannot create that evidence.\n\n## 5. Timestamp quality\n\nAlibaba contains time-like source fields and sampled telemetry timestamps, but their relationship to a V1 prediction decision is unknown. They are not upgraded to synchronized or exact runtime timestamps. Synthetic fixtures use controlled test timestamps only.\n\n## 6. Provenance and environment identity\n\nDataset/source provenance and one Alibaba trace identity are available at the historical data boundary. Complete runtime producer identity, source-record occurrence, clock basis, scheduler identity, node identity, and independent environment identity are not available. Multiple runs must not be labeled independent environments.\n\n## 7. Resource and telemetry feasibility\n\nSchema support exists for CPU/GPU/memory, allocation, utilization, contention, node, queue, and scheduler state. Current evidence only partially supports historical requested/resource aggregates and sampled telemetry; it does not support live decision-time resource or scheduler observations.\n\n## 8. Reproducibility\n\nThe existing event store and replay are deterministic for supplied canonical events. This is replayable data/infrastructure, not reproducible runtime observation. Alibaba preprocessing is reproducible at its documented boundary, but the original runtime event occurrence and synchronized clocks cannot be regenerated.\n\n## 9. Instrumentation decision\n\nNo legitimate existing runtime path justified a new adapter or controlled instrumentation. No fake source was created, no timestamps were invented, and no simulation was presented as infrastructure evidence.\n\n## 10. Validation and integrity\n\nExisting Phase 4 architecture and hardening tests were reused. New feasibility artifacts are isolated under this phase. V1 and historical Phase 3–4 artifacts remain protected. No model, detector, diagnosis, recovery, benchmark, or Phase 4.2 implementation was added.\n\n## 11. Final decision\n\n**D — NO LEGITIMATE RUNTIME SOURCE CURRENTLY AVAILABLE.** The reusable observability infrastructure is present, but the source gate is not satisfied.\n\n## 12. Phase 4.2 authorization\n\n**PHASE 4.2 AUTHORIZATION: NOT AUTHORIZED.** A future phase may revisit this decision only after an approved real or controlled runtime process can emit actual event occurrences with timestamp semantics, provenance, environment identity, and reproducible storage.\n'''
 write(OUT/'reports/PHASE4_1_1_SOURCE_FEASIBILITY_REPORT.md',report); write(OUT/'reports/PHASE4_1_1_SYNTHESIS.md',report+'\n## Engineering interpretation\n\nThe correct result is a truthful source block, not a fabricated positive result. Phase 4.1 remains engineering-ready/data-source limited.\n')
 files=sorted(p for p in OUT.rglob('*') if p.is_file() and p.name!='.finalized'); write(OUT/'hashes/manifest.json',json.dumps({'files':{str(p.relative_to(OUT)):sha(p) for p in files}},indent=2,sort_keys=True)+'\n'); files=sorted(p for p in OUT.rglob('*') if p.is_file() and p.name!='.finalized'); write(OUT/'.finalized',json.dumps({str(p.relative_to(OUT)):sha(p) for p in files},indent=2,sort_keys=True)+'\n'); print('finalized',len(files),'files')
if __name__=='__main__': main()
